<?php $e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');?>
<div class="section-heading"><div><div class="eyebrow">Aquisição</div><h1>Funil de conversão</h1><p class="text-secondary mb-0">Da visita à assinatura, por campanha e origem.</p></div><form method="get"><select class="form-select" name="days" onchange="this.form.submit()"><?php foreach([7,30,60,90,180] as $d):?><option value="<?=$d?>" <?=$days===$d?'selected':''?>>Últimos <?=$d?> dias</option><?php endforeach;?></select></form></div>
<div class="funnel-strip"><?php $labels=['PageView'=>'Visitas','ViewContent'=>'Interesse','Lead'=>'Leads','CompleteRegistration'=>'Cadastros','StartTrial'=>'Testes','Purchase'=>'Pagantes'];foreach($labels as $key=>$label):?><div><small><?=$label?></small><strong><?=(int)($counts[$key]??0)?></strong></div><?php endforeach;?></div>
<div class="card mt-4"><div class="card-header"><strong>Campanhas</strong></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Campanha</th><th>Origem</th><th>Visitas</th><th>Leads</th><th>Testes</th><th>Pagantes</th><th>Conversão</th></tr></thead><tbody><?php foreach($campaigns as $row):?><tr><td><?=$e($row['campaign'])?></td><td><?=$e($row['source'])?></td><td><?=(int)$row['visits']?></td><td><?=(int)$row['leads']?></td><td><?=(int)$row['trials']?></td><td><?=(int)$row['purchases']?></td><td><?=$row['visits']?number_format(100*(int)$row['trials']/(int)$row['visits'],1,',','.').' %':'—'?></td></tr><?php endforeach;?><?php if(!$campaigns):?><tr><td colspan="7" class="text-center text-secondary py-4">Ainda não há eventos no período.</td></tr><?php endif;?></tbody></table></div></div>
<div class="card mt-4"><div class="card-body"><strong>Conversion API</strong><div class="d-flex gap-3 flex-wrap mt-2"><?php foreach($meta as $row):?><span class="badge text-bg-light"><?=$e($row['status'])?>: <?=(int)$row['total']?></span><?php endforeach;?></div></div></div>
